entries[340068] = { ["name"] = "Sündenbehafteter Todeswandler", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Geschmiedet aus den Sünden unzähliger diabolischer Dungeonbewohner. Nur wer stark genug ist, sie zu bezwingen, vermag ihre Zügel zu halten.\"\nErfolg:\nSchlüsselsteinmeister von Shadowlands: Saison 1\nKategorie:\nDungeons" }
