entries[340070] = { ["name"] = "Weichklopfen", ["text"] = "8 Meter Reichweite\nWirken in 1.5 sek. 2 sek. Abklingzeit\nFügt einem Gegner 10 körperlichen Schaden zu und erhöht seinen erlittenen körperlichen Schaden 16 Sek. lang um 15%.\n\nDieser Effekt ist stapelbar." }
