entries[340075] = { ["name"] = "Eruption", ["text"] = "100 Meter Reichweite\nKanalisiert (Wirken in 10 sek.)\nVerwandelt das Ziel in einen Schleim." }
entries[340076] = { ["name"] = "Mal des Meisterassassinen", ["text"] = "Runenschnitzmacht\nErhöht in Verstohlenheit und 4 Sek. nach dem Verlassen der Verstohlenheit Eure kritische Trefferchance um 100%.\nRunenschnitzen: Handgelenk, Finger\nQuelle: Dungeonbeute: Ein Affront der Herausforderer\nBenötigt: Schurke" }
entries[340077] = { ["name"] = "Lebhafte Drachenfeder", ["text"] = "Sofort 15 min Abklingzeit\nEine mystische Drachenfeder verlangsamt Euren Fall für 10 Sek.\n\nKann nur in den Schattenlanden verwendet werden." }
entries[340078] = { ["name"] = "Winzige vergiftete Klinge", ["text"] = "Runenschnitzmacht\n'Tückische Klinge' verursacht 500% mehr Schaden und kostet keine Energie mehr.\nRunenschnitzen: Taille, Füße\nQuelle: Quest: Die Große Schatzkammer\nBenötigt: Schurke" }
entries[340079] = { ["name"] = "Essenz des Blutzahns", ["text"] = "Runenschnitzmacht\nEure Combopunkte erzeugenden Fähigkeiten haben eine Chance, das Ziel mit 'Blutzahn' zu infizieren, was ihm 0 Blutungsschaden im Verlauf von 6 Sek. zufügt und Euch um 50% des verursachten Schadens heilt.\n(Procchance: 30%, 200ms Abklingzeit)\nRunenschnitzen: Kopf, Schulter, Finger\nQuelle: Schlachtzugbeute: Generäle der Steinlegion\nBenötigt: Schurke" }
entries[340080] = { ["name"] = "Belebender Schattenstaub", ["text"] = "Runenschnitzmacht\n'Verschwinden' verringert die verbleibende Abklingzeit Eurer anderen Fähigkeiten um 20 Sek.\nRunenschnitzen: Hals, Brust\nQuelle: Gegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\nBenötigt: Schurke" }
entries[340081] = { ["name"] = "Bestechender Halunke", ["text"] = "Runenschnitzmacht\n'Vergiften' erhöht zusätzlich die kritische Trefferchance Eurer Gifte um 15% und deren kritische Treffer erzeugen 1 Energie.\nRunenschnitzen: Füße, Rücken\nQuelle: Schlachtzugbeute: Der Rat des Blutes\nBenötigt: Schurke (Meucheln)" }
entries[340082] = { ["name"] = "Verdammnisklinge", ["text"] = "Runenschnitzmacht\n'Verstümmeln' verursacht zusätzlich 45% Blutungsschaden im Verlauf von 8 Sek.\n\nDer Schaden von 'Vergiften' wird pro beim Ziel aktiven Blutungseffekt um 5% erhöht.\nRunenschnitzen: Schulter, Hände, Rücken\nQuelle: Beute von: Torghast, Turm der Verdammten. Mort'regar, Ebene 3+\nBenötigt: Schurke (Meucheln)" }
entries[340083] = { ["name"] = "Insigne von Zoldyck", ["text"] = "Runenschnitzmacht\nEure Gifte und Blutungseffekte fügen Zielen mit weniger als 30% Gesundheit 30% mehr Schaden zu.\nRunenschnitzen: Beine, Füße\nQuelle: Beute von: Torghast, Turm der Verdammten. Kaltherzinterstitia, Ebene 3+\nBenötigt: Schurke (Meucheln)" }
entries[340084] = { ["name"] = "Notlösung des Dämmergängers", ["text"] = "Runenschnitzmacht\nDie verbleibende Abklingzeit von 'Todesmal' wird pro 30 verbrauchter Energie um 1 Sek. verringert.\nRunenschnitzen: Brust, Finger\nQuelle: Dungeonbeute: Nebelruferin\nBenötigt: Schurke (Meucheln)" }
entries[340085] = { ["name"] = "Grünhauts Ruten", ["text"] = "Runenschnitzmacht\n'Zwischen die Augen' hat eine Chance von 20% pro Combopunkt, den Schaden Eures nächsten Einsatzes von 'Pistolenschuss' um 300% zu erhöhen.\nRunenschnitzen: Kopf, Taille\nQuelle: Schlachtzugbeute: Schlickfaust\nBenötigt: Schurke (Gesetzlosigkeit)" }
entries[340086] = { ["name"] = "Argliststalisman", ["text"] = "Runenschnitzmacht\nMacht Euch den natürlichen Verlauf eines Kampfes zunutze, sodass Eure Einsätze von 'Finsterer Stoß' im Laufe der Zeit Euren verursachten Schaden um bis zu 15% erhöhen. Dieses Maximum hält 12 Sek. lang an. Anschließend beginnt der Kreislauf von vorn.\nRunenschnitzen: Hals, Handgelenk\nQuelle: Weltbossbeute: Mortanis\nBenötigt: Schurke (Gesetzlosigkeit)" }
entries[340087] = { ["name"] = "Schnelligkeit", ["text"] = "Runenschnitzmacht\n'Adrenalinrausch' erhöht Euren Schaden um 8%, und während 'Zerhäckseln' aktiv ist, habt Ihr eine Chance, 3 Sek. lang den Effekt 'Adrenalinrausch' zu erhalten.\nRunenschnitzen: Schulter, Finger\nQuelle: Dungeonbeute: Ventunax\nBenötigt: Schurke (Gesetzlosigkeit)" }
entries[340088] = { ["name"] = "Verborgene Donnerbüchse", ["text"] = "Runenschnitzmacht\nWenn 'Finsterer Stoß' ein weiteres Mal trifft, besteht eine Chance von 40%, dass Euer nächster Einsatz von 'Pistolenschuss' 3-mal zusätzlich feuert.\nRunenschnitzen: Handgelenk, Hände\nQuelle: Beute von: Torghast, Turm der Verdammten. Die Seelenschmieden, Ebene 3+\nBenötigt: Schurke (Gesetzlosigkeit)" }
entries[340089] = { ["name"] = "Endgültigkeit", ["text"] = "Runenschnitzmacht\n'Ausweiden', 'Blutung' und 'Schwarzpulver' erhöhen den Schaden Eures nächsten Einsatzes dieses Finishing-Moves um 25%.\nRunenschnitzen: Brust, Rücken\nQuelle: Schlachtzugbeute: Graf Denathrius\nBenötigt: Schurke (Täuschung)" }
entries[340090] = { ["name"] = "Akaaris Seelenfragment", ["text"] = "Runenschnitzmacht\n2 Sek. nach dem Einsatz von 'Schattenschlag' oder 'Fieser Trick' erleidet Euer Ziel einen weiteren Schattenschlag mit 25% Effektivität.\nRunenschnitzen: Kopf, Hals, Hände\nQuelle: Beute von: Torghast, Turm der Verdammten. Skoldushalle, Ebene 3+\nBenötigt: Schurke (Täuschung)" }
entries[340091] = { ["name"] = "Die Verdorbenen", ["text"] = "Runenschnitzmacht\nNach der Aktivierung von 'Symbole des Todes' verursacht Euer nächster Einsatz von 'Schattenschlag' oder [ Düstere Klinge : 'Düstere Klinge' / 'Meucheln'] 50% mehr Schaden und erzeugt 4 zusätzliche Combopunkte.\nRunenschnitzen: Beine, Rücken\nQuelle: Dungeonbeute: Domina Giftklinge\nBenötigt: Schurke (Täuschung)" }
entries[340092] = { ["name"] = "Tödliche Schatten", ["text"] = "Runenschnitzmacht\n'Verschwinden' erzeugt 5 Combopunkte und erhöht sämtlichen verursachten Schaden für [ Täuschung : 15 Sek. um 20% /\n\nMeucheln, Gesetzlosigkeit\n12 Sek. um 15% ](500ms Abklingzeit)\nRunenschnitzen: Taille, Beine\nQuelle: Beute von: Torghast, Turm der Verdammten. Frakturkammern, Ebene 3+\nBenötigt: Schurke" }
