entries[340146] = { ["name"] = "Geladene Angriffe", ["text"] = "25 Energie\nWirken in 2.5 sek. 12 sek. Abklingzeit\nErhöht 12 Sek. lang das Angriffstempo des Zaubernden um 50%. Nahkampfangriffe lassen Energie explodieren und fügen Zielen innerhalb von 5 Metern 10 Arkanschaden zu.\n\nVerringert die Bewegungsgeschwindigkeit um 40%." }
entries[340147] = { ["name"] = "Königlicher Erlass", ["text"] = "Sofort\nDie Abklingzeit von 'Wächter der Uralten Könige' ist um 15.0 Sek . verringert und der Einsatz lässt Euren nächsten Einsatz von 'Wort der Herrlichkeit' keine Heilige Kraft kosten." }
