entries[340159] = { ["name"] = "Dienst in Stein", ["text"] = "Seelenbandefähigkeit\nBei weniger als 40% Gesundheit ist erlittener Schaden um 10% verringert. Beim Tod hinterlasst Ihr eine Steinhülle, die nach 3 Sek. zerspringt und 100% Eurer maximalen Gesundheit als körperlichen Schaden verursacht, der auf Gegner in der Nähe aufgeteilt wird, und 100% Eurer maximalen Gesundheit als Heilung hervorruft, die auf Verbündete innerhalb von 20 Metern aufgeteilt wird." }
entries[340160] = { ["name"] = "Strahlender Atem", ["text"] = "40 Meter Reichweite\nWirken in 3 sek.\nDer Zaubernde entfesselt strahlende Energie in einem kegelförmigen Bereich, die Zielen 0 Naturschaden zufügt und sie für 5 Sek. desorientiert." }
