entries[340201] = { ["name"] = "Schlundröcheln", ["text"] = "100 Meter Reichweite\nSofort\nBeim Töten eines Gegners besteht eine hohe Chance, eine explosive Schlundratte an der Position der Leiche zu beschwören. Nach 6 Sek. explodiert die Schlundratte, fügt allen Gegnern in der Nähe 31747 Naturschaden zu, vergiftet sie und verringert ihren verursachten Schaden 10 Sek. lang um 5%." }
entries[340202] = { ["name"] = "Fluch von Renagals Pakt", ["text"] = "Sofort\nNach Erhalt: Der Fluch von Renagals Pakt verlässt den Kelch und Gegner werden aus größerer Distanz als zuvor auf Euch aufmerksam." }
entries[340203] = { ["name"] = "Geheiligte Einsicht", ["text"] = "100 Meter Reichweite\nSofort\nWeiht den Zielbereich für 30 Sek. Gegner innerhalb des Bereichs erleiden bis zu [(55% der Zaubermacht) * 30 / 2] Schattenschaden und Verbündete werden um bis zu [(36% der Zaubermacht) * 30 / 2] Gesundheit geheilt. Die Werte verringern sich bei mehr als 5 Zielen.\n\nInnerhalb der Weihung könnt Ihr 'Hammer des Zorns' gegen jedes beliebige Ziel einsetzen und die Fähigkeit verursacht 100% mehr Schaden." }
entries[340206] = { ["name"] = "Fluch von Teramaniks Vermächtnis", ["text"] = "Sofort\nNach Erhalt: Der Fluch von Teramaniks Vermächtnis verlässt die Zügel und verhindert, dass Ihr Eure Reittiere rufen könnt." }
entries[340207] = { ["name"] = "Animalichtblitz", ["text"] = "Wirken in 2.5 sek.\nDisorients enemies within 10 yards of the caster for 5 Sek..\nInflicts 20 Arcane damage to enemies within 10 yards." }
entries[340208] = { ["name"] = "Rüstung schreddern", ["text"] = "10 Meter Reichweite\nWirken in 1.5 sek.\nZerfetzt die Rüstung eines Gegners, verursacht 14529943 körperlichen Schaden und erhöht den erlittenen Schaden 20 Sek. lang um 20%." }
